import i18n from "i18next";
import { initReactI18next } from "react-i18next";
import data from "./data";

const resources = {
  en: {
    translation: data.ko
  },
  ko: {
    translation: data.en
  }
};

i18n
  .use(initReactI18next)
  .init({
    resources,
    lng: "ko",
    fallbackLng: "en",
    interpolation: {
      escapeValue: false
    }
  });

export default i18n;
